# Language: jac
"""Calculate the D-efficiency bound of an array extension."""
def DefficiencyBound(D: float, k: int, k2: int) -> float {
    m = 1.0 + k + (k * (k - 1)) / 2;
    m2 = 1.0 + k2 + (k2 * (k2 - 1)) / 2;
    return D ** (m / m2);
}

# Language: jac
"""Return the median value of `sorted_seq`.

    >>> median ([1, 2, 2, 3, 14])
    2

    >>> median ([1, 2, 2, 3, 3, 14])
    2.5

    """
def median_s(sorted_seq: list[int | float]) -> int | float {
    length = len(sorted_seq);
    if length % 2 {
        return sorted_seq[length // 2];
    }
    mid = (length // 2) - 1;
    return (sorted_seq[mid] + sorted_seq[mid + 1]) / 2.0;
}

# Language: Jac
"""Parses the word and counts the number of digits, lowercase letters,
    uppercase letters, and symbols. Returns a dictionary with the results.
    If any character in the word is not in the set of digits, lowercase
    letters, uppercase letters, or symbols it is marked as a bad character.
    Words with bad characters are not output."""
def parse_word(word: Any, s: Any) -> object {
    count = {'d': 0, 'l': 0, '': 0, 's': 0, 'x': 0};
    d = '0123456789';
    l = 'abcdefghijklmnopqrstuvwxyz';
    u = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    for c in word {
        if (c in d) {
            count['d'] += 1;
        } elif (c in l) {
            count['l'] += 1;
        } elif (c in u) {
            count[''] += 1;
        } elif (c in s) {
            count['s'] += 1;
        } else {
            count['x'] += 1;
        }
    }
    return count;
}

