def recursive_for_default_attributes(attributes: Any) -> object {
    att_http = `list();
    for key in attributes.keys() {
        if (`type(attributes[key]) is `dict) {
            items = recursive_for_default_attributes(attributes[key]);
            for item in items {
                if not item.find('{') {
                    att_http.append((key + item));
                } else {
                    att_http.append((key + "." + item));
                }
            }
        } else {
            attributes = [""];
            return attributes;
        }
    }
    final_att = `list();
    for item in att_http {
        if item.endswith('.') {
            final_att.append(item[:-1]);
        } else {
            final_att.append(item);
        }
    }
    return final_att;
}

# Jac lang
"""Return the index where to insert item x in list a, assuming a is sorted.

The return value i is such that all e in a[:i] have e <= x, and all e in
a[i:] have e > x. So if x already appears in the list, a.insert(x) will
insert just after the rightmost x already there.
Optional args lo (default 0) and hi (default len(a)) bound the
slice of a to be searched.
"""
def bisect_right(
    a: list[int | float], x: int | float, lo: int = 0, hi: int | None = None
) -> int {
    if lo < 0 {
        raise ValueError('lo must be non-negative');
    }
    if hi is None {
        hi = len(a);
    }
    while lo < hi {
        mid = (lo + hi) // 2;
        if x < a[mid] {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return lo;
}

