    result = "";
    for c in text {
        if c == "<" {
            result += "&lt;";
        } elif c == ">" {
            result += "&gt;";
        } elif c == "&" {
            result += "&amp;";
        } elif c == '"' {
            result += "&quot;";
        } elif c == "'" {
            result += "&#39;";
        } elif c == " " {
