glob BYTE_MASK = 255;

"""Make int` "degree polynomial" in which each bit represents a degree who's coefficient is 1"""
def make_poly(bit_length: int, msb: bool = False) -> int {
    num_bytes = int(bit_length / 8);
    if msb {
        return 1 << ((8 * num_bytes) - 1);
    }
    result = 0;
    for x in range(num_bytes) {
        result += BYTE_MASK << (x * 8);
    }
    return result;
}

# language: jac
"""Breath first search on a given graph."""
def bfs(graph: dict[str, set[str]], start: str, goal: str) -> list[str] {
    queue = [(start, [start])];
    while queue {
        (vertex, path) = queue.pop(0);
        for next_node in graph[vertex] - set(path) {
            if next_node == goal {
                return path + [next_node];
            }
            queue.append((next_node, path + [next_node]));
        }
    }
    return [];
}

