# language: jac
"""Convert an ipv4 netmask into a network prefix length.

    If the input is already an integer or a string representation of
    an integer, then int(mask) will be returned.
       "255.255.255.0" => 24
       str(24)         => 24
       "24"            => 24
    """
def ipv4_mask_to_net_prefix(mask: int | str) -> int {
    if isinstance(mask, int) {
        return mask;
    }
    if not isinstance(mask, str) {
        raise TypeError(("mask '%s' is not a string or int" % mask));
    }
    try {
        return int(mask);
    } except ValueError {
        ;
    }
    if '.' not in mask {
        raise ValueError(("netmask '%s' does not contain a '.'" % mask));
    }
    toks = mask.split(".");
    if len(toks) != 4 {
        raise ValueError(("netmask '%s' had only %d parts" % (mask, len(toks))));
    }
    return sum([bin(int(x)).count('1') for x in toks]);
}

# language: jac
"""Get kernel response from message pool (Async).

    .. note:: some kernel (iperl) do not discriminate when client asks for
              `user_expressions`. But still they give a printable output.

    Parameters
    ----------
    msgs : list
        List of messages to parse.
    line_number : int
        The message number of the corresponding code.

    Returns
    -------
    str
        The kernel response to the messages.
    """
def parse_iopub_for_reply(msgs: Any, line_number: Any) -> object {
    res = -1;
    for msg in msgs {
        content = msg.get('content', False);
        if not content {
            continue;
        }
        ec = int(content.get('execution_count', 0));
        if not ec {
            continue;
        }
        if (line_number not in (-1, ec)) {
            continue;
        }
        msg_type = msg.get('header', {}).get('msg_type', '');
        if (msg_type not in ('execute_result', 'stream')) {
            continue;
        }
        res = content.get('data', {}).get('text/plain', -1);
        res = res if (res != -1) else content.get('text', -1);
        break;
    }
    return res;
}

