"""
    :return: a single value from lists, tuples or sets with one item;
    otherwise, the value itself if not empty or the default if it is.
    """
def reduce_value(value: Any, `default: Any = '') -> object {
    if hasattr(value, '__len__') {
        vlen = len(value);
        if (vlen == 0) {
            return `default;
        } elif (vlen == 1) {
            if isinstance(value, `set) {
                return value.pop();
            } elif isinstance(value, (`list, `tuple)) {
                return value[0];
            }
        }
    }
    return `default if (value is None) else value;
}

# Language: jac
"""Calculates the Fourier number from thermal diffusion parameters."""
def fourier_number(
    conductive_length_scale: float,
    conductivity: float,
    density: float,
    heat_capacity: float,
    time_scale: float
) -> float {
    (conductivity * time_scale)
        / (heat_capacity * density * (conductive_length_scale ** 2))
}

